/**
 * Rosters, coaches and in-game leaders per international event, from Liquipedia (CC-BY-SA 3.0).
 * Generated by scripts/liquipedia/run.mjs — do not edit events.json by hand. See docs/data.md.
 */
import eventsJson from './events.json';

export type IglSource =
  | 'event-captain'
  | 'squad-captain'
  | 'infobox-unique'
  | 'event-ambiguous'
  | 'infobox-ambiguous'
  | 'conflict'
  | 'none';

export interface LiquipediaPlayer {
  /** Canonical Liquipedia page title (null when the player has no page). */
  liquipediaId: string | null;
  /** Handle as written on the event page. */
  handle: string;
  /** ISO 3166-1 alpha-2, uppercase (same convention as Card.country). */
  flag: string | null;
  isSub: boolean;
  /** Substitute who did not play. */
  dnp?: boolean;
  vlrPlayerId?: string;
}

export interface LiquipediaPerson {
  name: string;
  liquipediaId: string | null;
}

export interface LiquipediaTeam {
  name: string;
  liquipediaPage: string | null;
  vlrTeamId: string | null;
  players: LiquipediaPlayer[];
  coach: LiquipediaPerson | null;
  staff: (LiquipediaPerson & { role: string })[];
  /** Handle of the in-game leader, or null when unknown/ambiguous. */
  igl: string | null;
  iglSource: IglSource;
  iglCandidates?: string[];
}

export interface LiquipediaEvent {
  id: string;
  name: string;
  tier: 'masters' | 'champions';
  year: number;
  startDate: string | null;
  endDate: string | null;
  vlrEventId: string | null;
  liquipedia: { title: string; revid: number; url: string; format: string; rosterSource: string };
  withdrawn: string[];
  teams: LiquipediaTeam[];
}

export interface LiquipediaData {
  source: { site: string; url: string; license: string; licenseUrl: string; credit: string };
  events: LiquipediaEvent[];
  /** Every page read, with the revision used (CC-BY-SA attribution). */
  sources: { title: string; revid: number }[];
}

export const LIQUIPEDIA = eventsJson as unknown as LiquipediaData;
export const LIQUIPEDIA_EVENTS: LiquipediaEvent[] = LIQUIPEDIA.events;
